#[crate::test]
async fn doesnt_panic_if_used_with_nested_router() {
    async fn handler() {}

    let routes_static =
        Router::new().nest_service("/", crate::routing::get_service(handler.into_service()));

    let routes_all = Router::new().fallback_service(routes_static);

