use axum::{get, routing::Router};
use http::{Request, StatusCode};
use tower::ServiceExt;

async fn body(app: Router, path: &str) -> (StatusCode, String) {
    let res = app
        .oneshot(Request::builder().uri(path).body(axum::body::Body::empty()).unwrap())
        .await
        .unwrap();
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body()).await.unwrap();
    (status, String::from_utf8(bytes.to_vec()).unwrap())
}

#[tokio::main]
async fn main() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new()
        .nest("/nested", nested_routes)
        .merge(other_router);

    assert_eq!(body(app.clone(), "/nested/some-route").await, (StatusCode::OK, "nested".into()));
    assert_eq!(body(app.clone(), "/other").await, (StatusCode::OK, "other".into()));
    assert_eq!(body(app.clone(), "/nested/foo").await, (StatusCode::OK, "fallback".into()));
    assert_eq!(body(app, "/foo").await.0, StatusCode::NOT_FOUND);

    let nested_routes = Router::new().fallback(|| async { "inner" });
    let app = Router::new()
        .nest("/nested", nested_routes)
        .fallback(|| async { "outer" })
        .merge(Router::new().route("/other", get(|| async { "other" })));
    assert_eq!(body(app.clone(), "/nested/foo").await, (StatusCode::OK, "inner".into()));
    assert_eq!(body(app, "/foo").await, (StatusCode::OK, "outer".into()));

    let app = Router::new()
        .nest("/a", Router::new().fallback(|| async { "a" }))
        .merge(Router::new().nest("/b", Router::new().fallback(|| async { "b" })));
    assert_eq!(body(app.clone(), "/a/foo").await, (StatusCode::OK, "a".into()));
    assert_eq!(body(app, "/b/foo").await, (StatusCode::OK, "b".into()));

    let app = Router::new()
        .merge(Router::new().nest("/b", Router::new().fallback(|| async { "b" })))
        .fallback(|| async { "outer" });
    assert_eq!(body(app.clone(), "/b/foo").await, (StatusCode::OK, "b".into()));
    assert_eq!(body(app, "/foo").await, (StatusCode::OK, "outer".into()));

    println!("all ok");
}

